let state=(()=>{try{return JSON.parse(THIS_LOCAL_STORAGE.getItem('this-agreement-studio-v1')||'null')||defaultState();}catch(error){console.warn('Unable to load the browser agreement draft; starting from the CRM payload.',error);return defaultState();}})();let editMode=false,zoom='fit',sigDrawn=false,editingProfessionalFeeId='';
function esc(v=''){return String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function save(){THIS_LOCAL_STORAGE.setItem('this-agreement-studio-v1',JSON.stringify(state));$('#saveStatus').textContent='Saved '+new Date().toLocaleTimeString('en-NZ',{hour:'2-digit',minute:'2-digit'});toast('Draft saved in this browser')}
function currentType(){return APP_TYPES[state.appType]||APP_TYPES.other}function fullClient(){return state.client.clientName||'Client'}
function activeSections(){return state.sections.filter(s=>s.enabled)}
function sectionNumber(id){let n=0;for(const s of state.sections){if(!s.enabled)continue;if(s.numberMode==='auto')n++;if(s.id===id){if(s.numberMode==='none')return '';if(s.numberMode==='manual')return s.manualNumber||'';return String(n).padStart(2,'0')}}return ''}
function heading(section){const num=sectionNumber(section.id);return `<div class="heading">${num?`<span class="n editable" data-edit="number" data-id="${section.id}">${esc(num)}</span>`:''}<h2 class="editable" data-edit="title" data-id="${section.id}">${esc(section.title)}</h2></div>`}
function bodyHtml(section){return `<div class="editable" data-edit="body" data-id="${section.id}">${section.body}</div>`}
function cover(){return `<article class="a4 cover"><div class="covermain"><img class="coverlogo" src="data:image/png;base64,"><div class="coverkicker"><span class="coverbar"></span><h1 class="editable" data-edit="coverHeading">${esc(state.template.coverHeading)}</h1></div><div class="covertitle editable" data-edit="coverSubtitle">${esc(state.template.coverSubtitle)}</div></div><div class="coverimg"></div><div class="coverfooter"><strong>PREPARED FOR - ${esc(fullClient().toUpperCase())}<br>DATE - ${esc(formatDate(state.client.preparedDate).toUpperCase())}</strong><em>www.turnerhopkinsimmigration.co.nz</em></div></article>`}
function formatDate(v){if(!v)return'';const d=new Date(v+'T00:00:00');return d.toLocaleDateString('en-NZ',{day:'numeric',month:'long',year:'numeric'})}
function page(inner,no){return `<article class="a4"><div class="pagebody">${inner}</div><span class="pageno">${no}</span></article>`}
function scopeList(){return state.scope.filter(x=>x.enabled).map(x=>`<div class="scopeitem"><span class="dot"></span><div>${esc(x.text)}</div></div>`).join('')}
function professionalTable(){return `<table class="feetable"><thead><tr><th>Payment</th><th>Professional service</th><th>When payable</th><th style="text-align:right">Amount</th></tr></thead><tbody>${state.professionalFees.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.description)}</td><td>${esc(r.trigger)}</td><td class="amount">${esc(r.amount)}</td></tr>`).join('')}</tbody></table>`}
function govTable(){return `<table class="feetable"><thead><tr><th>Agency</th><th>Application</th><th>Quantity</th><th>Notes</th><th style="text-align:right">Fee</th></tr></thead><tbody>${state.governmentFees.length?state.governmentFees.map(r=>`<tr><td>${esc(r.agency)}</td><td>${esc(r.application)}</td><td>${esc(r.quantity)}</td><td>${esc(r.note)}</td><td class="amount">${esc(r.amount)}</td></tr>`).join(''):`<tr><td colspan="5">No government fees have been added.</td></tr>`}</tbody></table>`}
function signatoryBoxes(){return state.signatories.map(s=>`<div class="acceptcell"><span>${esc(s.role)}</span><strong>${esc(s.name||'Name to be confirmed')}</strong><div class="signatureline"></div><div class="signlabel">Electronic acceptance / signature</div></div>`).join('')}
function sectionBlock(id,extra=''){const s=state.sections.find(x=>x.id===id);if(!s||!s.enabled)return'';return `<section class="section" data-section="${id}">${heading(s)}${bodyHtml(s)}${extra}</section>`}
function sectionExtra(id){
 if(id==='introduction')return `<div class="softbox" style="margin-top:16px"><h3>Agreed scope of services</h3>${scopeList()}</div><div class="note"><strong>Specific matter:</strong> ${esc(state.client.matterNote)}</div>`;
 if(id==='professional')return `${professionalTable()}<div class="note">Professional fees are exclusive of the ${esc(state.template.adminFee)}. GST will be added where applicable.</div>`;
 if(id==='government')return `${govTable()}<div class="note">The fee table is a working schedule and must be checked against current agency charges before issue.</div>`;
 if(id==='terms')return `<div class="note"><strong>Expected service period:</strong> ${esc(state.client.expectedMonths)}. <strong>Additional work rate:</strong> ${esc(state.template.hourlyRate)}.</div>`;
 if(id==='authorisation')return `<div class="acceptbox"><div class="acceptgrid">${signatoryBoxes()}</div><p style="margin-top:14px">${esc(state.acceptanceText)}</p></div>`;
 if(id==='payment')return `<div class="note"><strong>Overdue interest:</strong> ${esc(state.template.interestRate)}.</div>`;
 return '';
}
function nodeHtml(node){
 if(node.nodeType===Node.TEXT_NODE){const text=node.textContent.trim();return text?`<p>${esc(text)}</p>`:''}
 return node.outerHTML||'';
}
function sectionFlowUnits(section){
 const shell=document.createElement('div');
 shell.innerHTML=`<section>${heading(section)}${bodyHtml(section)}${sectionExtra(section.id)}</section>`;
 const root=shell.firstElementChild;
 const body=root.querySelector(':scope > [data-edit="body"]');
 const parts=[];
 if(body){
  [...body.childNodes].map(nodeHtml).filter(Boolean).forEach(html=>parts.push({html:`<div class="editable body-fragment" data-edit="body" data-id="${section.id}">${html}</div>`,body:true}));
  let sibling=body.nextSibling;
  while(sibling){const html=nodeHtml(sibling);if(html)parts.push({html,body:false});sibling=sibling.nextSibling}
 }
 if(!parts.length)parts.push({html:`<div class="editable body-fragment" data-edit="body" data-id="${section.id}"></div>`,body:true});
 return parts.map((part,index)=>{
  const first=index===0,last=index===parts.length-1;
  const classes=['section','fragment',first?'fragment-first':'fragment-continuation',last?'fragment-last':''].filter(Boolean).join(' ');
  const content=`<section class="${classes}" data-section="${section.id}">${first?heading(section):''}${part.html}</section>`;
  const continued=`<section class="${classes}" data-section="${section.id}"><div class="continuation-heading">${esc(section.title)} <span>continued</span></div>${part.html}</section>`;
  return {sectionId:section.id,title:section.title,first,last,html:content,continuedHtml:continued};
 });
}
function measurePageContent(html){
 const probe=document.createElement('div');
 probe.className='page-measure';
 probe.innerHTML=`<div class="pagebody">${html}</div>`;
 document.body.appendChild(probe);
 const height=Math.ceil(probe.querySelector('.pagebody').getBoundingClientRect().height);
 probe.remove();
 return height;
}
function paginateSectionFlow(sections){
 const pages=[];
 let current='';
 sections.forEach(section=>{
  const units=sectionFlowUnits(section);
  units.forEach((unit,index)=>{
   const candidate=current+unit.html;
   if(current&&measurePageContent(candidate)>1123){
    pages.push(current);
    current=index>0?unit.continuedHtml:unit.html;
   }else{
    current=candidate;
   }
  });
 });
 if(current)pages.push(current);
 return pages;
}
function renderPages(){
 const sections=state.sections.filter(section=>section.enabled);
 const paginated=paginateSectionFlow(sections);
 let n=1,out=cover();
 paginated.forEach(inner=>{out+=page(inner,n++)});
 $('#pages').innerHTML=out;
 $('#pages').className='pages '+zoom;
 $('#previewTitle').textContent=currentType().title+' engagement agreement';
 $('#pages').classList.toggle('editmode',editMode);
 bindInlineEdits();
}
function renderSectionList(){let auto=0;$('#sectionList').innerHTML=state.sections.map(s=>{if(s.enabled&&s.numberMode==='auto')auto++;let label=s.numberMode==='none'?'—':s.numberMode==='manual'?(s.manualNumber||'•'):String(auto).padStart(2,'0');return `<div class="sectioncard ${state.selectedSection===s.id?'active':''}" data-section-select="${s.id}"><div class="num">${esc(label)}</div><div class="sectioncopy"><strong>${esc(s.title)}</strong><small>${esc(s.note)}</small></div><input type="checkbox" data-section-toggle="${s.id}" ${s.enabled?'checked':''}></div>`}).join('');$$('[data-section-select]').forEach(el=>el.addEventListener('click',e=>{if(e.target.matches('input'))return;state.selectedSection=el.dataset.sectionSelect;renderContentEditor();renderSectionList()}));$$('[data-section-toggle]').forEach(cb=>cb.addEventListener('change',e=>{state.sections.find(s=>s.id===cb.dataset.sectionToggle).enabled=e.target.checked;dirty();renderAll()}))}
function renderContentEditor(){const s=state.sections.find(x=>x.id===state.selectedSection)||state.sections[0];$('#sectionTitleHeading').textContent=s.title;$('#sectionTitleInput').value=s.title;$('#sectionBodyInput').value=s.body;$('#numberMode').value=s.numberMode;$('#manualNumber').value=s.manualNumber||'';$('#manualNumberWrap').style.visibility=s.numberMode==='manual'?'visible':'hidden'}
function renderMatter(){$$('.matter').forEach(el=>el.value=state.client[el.dataset.key]||'');$('#scopeRows').innerHTML=state.scope.map((r,i)=>`<div class="repeatrow" data-scope-row="${i}"><div class="checkrow"><input type="checkbox" data-scope-enable ${r.enabled?'checked':''}><input class="input" data-scope-text value="${esc(r.text)}"></div><div class="rowactions"><button class="btn danger small" data-scope-remove>Remove</button></div></div>`).join('');bindRepeats()}
function renderFees(){$('#profRows').innerHTML=state.professionalFees.map((r,i)=>`<article class="fee-editor-card" data-prof-row="${i}"><div class="fee-editor-number">${i+1}</div><div class="fee-editor-copy"><strong>${esc(r.description||'Untitled payment stage')}</strong><span class="fee-editor-amount">${esc(r.amount||'Amount not set')}</span><p>${esc(r.trigger||'Payment trigger not set')}</p></div><div class="fee-editor-actions"><button class="btn secondary small" data-prof-edit>Edit</button><button class="btn danger small" data-prof-remove>Remove</button></div></article>`).join('');$('#govRows').innerHTML=state.governmentFees.map((r,i)=>`<div class="repeatrow" data-gov-row="${i}"><div class="inlinegrid four"><input class="input" data-gf="application" value="${esc(r.application)}"><input class="input" data-gf="amount" value="${esc(r.amount)}"><input class="input" data-gf="quantity" value="${esc(r.quantity)}"><input class="input" data-gf="note" value="${esc(r.note)}"></div><div class="field" style="margin:8px 0 0"><input class="input" data-gf="agency" value="${esc(r.agency)}" placeholder="Agency"></div><div class="rowactions"><button class="btn danger small" data-gov-remove>Remove</button></div></div>`).join('');bindRepeats()}
function renderSigning(){ $('#signatoryRows').innerHTML=state.signatories.map((r,i)=>`<div class="repeatrow" data-sign-row="${i}"><div class="inlinegrid"><input class="input" data-sf="name" value="${esc(r.name)}"><input class="input" data-sf="email" value="${esc(r.email)}"><input class="input" data-sf="role" value="${esc(r.role)}"></div><label class="checkrow"><input type="checkbox" data-sf-required ${r.required?'checked':''}>Required signature</label><div class="rowactions"><button class="btn danger small" data-sign-remove>Remove</button></div></div>`).join('');$('#acceptanceText').value=state.acceptanceText;$('#emailSubject').value=state.emailSubject;$('#emailBody').value=state.emailBody;bindRepeats()}
function renderTemplate(){ $$('.template').forEach(el=>el.value=state.template[el.dataset.key]||'');$('#versionHistory').innerHTML=state.templateHistory.slice().reverse().map(h=>`<div class="historyitem"><div><strong>Version ${esc(h.version)}</strong><small>${esc(h.date)} - ${esc(h.note)}</small></div><button class="btn secondary small" disabled>Published</button></div>`).join('')}
function renderHeader(){const t=currentType();$('#leftTitle').textContent=t.title;$('#summaryName').textContent=fullClient();$('#summaryMatter').textContent=t.short+' engagement agreement';$('#statusPill').textContent=state.status;$('#feeConfirmed').checked=!!state.feeConfirmed;$('#clientChecked').checked=!!state.clientChecked;$('#sourceMode').value=state.sourceMode;$('#appType').value=state.appType}
function renderAll(){renderHeader();renderSectionList();renderContentEditor();renderMatter();renderFees();renderSigning();renderTemplate();renderPages()}
