(function(){
  const CRM_ORIGIN = window.location.origin;
  let crmContext = { agreementSetId:'', canManageTemplates:false };
  let crmInitialised = false;
  let readyHandshakeTimer = 0;
  let publicToken = '';
  let publicSignatory = null;
  const clone = value => JSON.parse(JSON.stringify(value == null ? {} : value));
  const post = (type,payload={}) => {
    if(window.parent===window) return;
    window.parent.postMessage({source:'this-agreement-studio',type,...payload},CRM_ORIGIN);
  };
  function appTypeFromCaseType(caseType=''){
    const value=String(caseType||'').toLowerCase();
    if(value.includes('smc')||value.includes('skilled migrant')) return 'smc';
    if(value.includes('active investor')||value.includes('investor')) return 'investor';
    if(value.includes('parent')) return 'parent';
    if(value.includes('partner residence')||value.includes('partnership')) return 'partnership';
    if(value.includes('accreditation')) return 'accreditation';
    if(value.includes('aewv')) return 'aewv';
    if(value.includes('student')) return 'student';
    if(value.includes('visitor')) return 'visitor';
    if(value.includes('permanent residence')) return 'permanent';
    if(value.includes('citizenship')) return 'citizenship';
    return 'other';
  }
  function fullName(person={}){ return [person.firstName,person.lastName].filter(Boolean).join(' ').trim() || person.name || ''; }
  function mapClient(client={},advisers=[]){
    const family=Array.isArray(client.familyMembers)?client.familyMembers:[];
    const partner=family.find(member=>/partner|spouse|husband|wife/i.test(member.relationship||member.type||member.role||''));
    const primary=advisers.find(item=>item.id===client.primaryAdviserId)||{};
    const principal=fullName(client)||'Client';
    const partnerName=fullName(partner);
    return {
      clientName:principal,
      partnerName,
      clientEmail:client.email||'',
      matterRef:client.oneLawClientNumber||client.matterName||client.id||'',
      adviserName:primary.name||'',
      adviserEmail:primary.email||'',
      preparedDate:new Date().toISOString().slice(0,10),
      expectedMonths:'To be confirmed',
      matterNote:client.caseStrategy||client.caseType||''
    };
  }
  function applyMasterTemplate(next,library){
    const master=library&&typeof library==='object'?library.masterState:null;
    if(!master||typeof master!=='object') return next;
    const preserved={client:next.client,appType:next.appType,sourceMode:next.sourceMode,status:next.status,sentAt:next.sentAt,acceptedAt:next.acceptedAt,acceptedBy:next.acceptedBy,token:next.token,scope:next.scope,governmentFees:next.governmentFees,professionalFees:next.professionalFees,signatories:next.signatories,emailSubject:next.emailSubject,emailBody:next.emailBody};
    const merged={...clone(next),...clone(master),...preserved};
    merged.client={...(master.client||{}),...preserved.client};
    return merged;
  }
  function hydrateLinkedClient(next,payload={}){
    if(payload.intake) next.sourceMode='intake';
    else if(payload.client) next.sourceMode='linked';
    else next.sourceMode='standalone';
    if(!payload.client) return next;
    const existing=next.client||{};
    const mapped=mapClient(payload.client,payload.advisers||[]);
    next.client={
      ...existing,
      ...mapped,
      preparedDate:existing.preparedDate||mapped.preparedDate,
      expectedMonths:existing.expectedMonths||mapped.expectedMonths,
      matterNote:mapped.matterNote||existing.matterNote||''
    };
    const signatories=Array.isArray(next.signatories)?next.signatories:[];
    let principal=signatories.find(item=>/principal|client/i.test(item.role||''));
    if(!principal){
      principal={id:'sg-'+Date.now(),role:'Principal client',required:true};
      signatories.unshift(principal);
    }
    principal.name=next.client.clientName||principal.name||'';
    principal.email=next.client.clientEmail||principal.email||'';
    if(next.client.partnerName){
      let partner=signatories.find(item=>/partner|second client/i.test(item.role||''));
      if(!partner){
        partner={id:'sg-'+(Date.now()+1),role:'Partner / second client',required:true};
        signatories.push(partner);
      }
      partner.name=next.client.partnerName;
    }
    next.signatories=signatories;
    return next;
  }
  function createState(payload={}){
    const saved=payload.agreementSet?.studioState;
    if(saved&&typeof saved==='object'&&Object.keys(saved).length){
      const restored=hydrateLinkedClient(clone(saved),payload);
      if(!payload.client&&payload.agreementSet?.standaloneLabel){
        restored.sourceMode='standalone';
        restored.client={...(restored.client||{}),clientName:payload.agreementSet.standaloneLabel,matterRef:payload.agreementSet.standaloneLabel,clientEmail:payload.agreementSet.recipientEmail||restored.client?.clientEmail||''};
      }
      return restored;
    }
    let next=defaultState();
    next.status=payload.agreementSet?.status||'Draft';
    next.appType=payload.agreementSet?.appType||appTypeFromCaseType(payload.client?.caseType||'');
    if(!APP_TYPES[next.appType]) next.appType='other';
    next.template.coverSubtitle=APP_TYPES[next.appType].title;
    next.scope=APP_TYPES[next.appType].scope.map((text,i)=>({id:'s'+Date.now()+i,text,enabled:true}));
    next.governmentFees=APP_TYPES[next.appType].gov.map((r,i)=>({id:'g'+Date.now()+i,agency:r[0],application:r[1],quantity:r[2],amount:r[3],note:r[4]}));
    next.client=mapClient(payload.client||{},payload.advisers||[]);
    next.sourceMode=payload.intake?'intake':payload.client?'linked':'standalone';
    if(!payload.client&&payload.agreementSet?.standaloneLabel){
      next.client.clientName=payload.agreementSet.standaloneLabel;
      next.client.matterRef=payload.agreementSet.standaloneLabel;
      next.client.clientEmail=payload.agreementSet.recipientEmail||'';
    }
    const signatories=[];
    if(next.client.clientName) signatories.push({id:'sg-'+Date.now(),name:next.client.clientName,email:next.client.clientEmail||'',role:'Principal client',required:true});
    if(next.client.partnerName) signatories.push({id:'sg-'+(Date.now()+1),name:next.client.partnerName,email:'',role:'Partner / second client',required:true});
    next.signatories=signatories.length?signatories:next.signatories;
    next.emailBody=`Dear ${String(next.client.clientName||'client').split(' ')[0]},

Please use the secure link below to review and accept your Turner Hopkins engagement agreement. If any detail is incorrect or you have a question, please contact us before accepting it.

Kind regards
${next.client.adviserName||'Turner Hopkins Immigration Specialists'}`;
    return hydrateLinkedClient(applyMasterTemplate(next,payload.templateLibrary||{}),payload);
  }
  function currentSnapshot(){
    return {
      title:`${state.client.clientName||'Agreement'} - ${currentType().title}`,
      appType:state.appType,
      status:state.status||'Draft',
      studioState:clone(state),
      templateVersion:{version:state.template?.version||'1.0'},
      recipientEmail:state.client?.clientEmail||'',
      adviserEmail:state.client?.adviserEmail||'',
      signatories:clone(state.signatories||[])
    };
  }
  function emitSnapshot(reason='save'){ post('THIS_AGREEMENT_SNAPSHOT',{reason,agreementSetId:crmContext.agreementSetId,snapshot:currentSnapshot()}); }
  function emitTemplate(reason='save'){
    const library={masterState:clone(state),updatedAt:new Date().toISOString()};
    const versionEvent=reason==='publish'?{versionLabel:state.template?.version||'1.0',changeNote:(document.querySelector('#changeNote')?.value||'').trim(),snapshot:clone(state)}:null;
    post('THIS_AGREEMENT_TEMPLATE_LIBRARY',{reason,library,versionEvent});
  }
  function setCrmPresentation(){
    document.body.classList.add('crm-embedded-agreement');
    const product=document.querySelector('.product'); if(product) product.textContent='Agreement Studio';
    const subtitle=document.querySelector('.subtitle'); if(subtitle) subtitle.textContent='CRM agreement authoring';
    document.title='THiS Agreement Studio';
    const saveBtn=document.querySelector('#saveBtn'); if(saveBtn) saveBtn.textContent='Save to CRM';
    const issueBtn=document.querySelector('#issueBtn'); if(issueBtn) issueBtn.textContent='Issue agreement';
    const notice=document.querySelector('.preview>.notice'); if(notice) notice.textContent='Review client details, fees and terms before issue';
  }
  function setPublicPresentation(){
    document.body.classList.add('public-review-mode');
    document.body.classList.remove('crm-embedded-agreement');
    const product=document.querySelector('.product'); if(product) product.textContent='Agreement';
    const subtitle=document.querySelector('.subtitle'); if(subtitle) subtitle.textContent='Turner Hopkins Immigration Specialists';
    const notice=document.querySelector('.preview>.notice'); if(notice) notice.textContent='Please review this agreement carefully before accepting it.';
    const audit=document.querySelector('.audit'); if(audit) audit.textContent='Your acceptance records the agreement version, the document accepted, your name and signature, the date and time, your email address and technical audit details.';
    document.title='Agreement | Turner Hopkins Immigration Specialists';
  }
  function initFromCrm(payload={}){
    const incomingId=String(payload.agreementSet?.id||'');
    if(crmInitialised&&incomingId&&crmContext.agreementSetId===incomingId&&!payload.force){
      post('THIS_AGREEMENT_INITIALISED',{agreementSetId:crmContext.agreementSetId,appType:state.appType,sourceMode:state.sourceMode});
      return;
    }
    crmContext={agreementSetId:incomingId,canManageTemplates:Boolean(payload.canManageTemplates)};
    state=createState(payload);
    crmInitialised=true;
    if(readyHandshakeTimer) window.clearInterval(readyHandshakeTimer);
    if(!crmContext.canManageTemplates) document.querySelector('#templateBtn')?.remove();
    renderAll();
    setCrmPresentation();
    post('THIS_AGREEMENT_INITIALISED',{agreementSetId:crmContext.agreementSetId,appType:state.appType,sourceMode:state.sourceMode});
  }
  async function loadPublicReview(token){
    publicToken=token;
    document.body.classList.add('public-review-mode');
    const response=await fetch(`/api/agreement?token=${encodeURIComponent(token)}`,{headers:{accept:'application/json'}});
    const payload=await response.json().catch(()=>({}));
    if(!response.ok||!payload.agreement){
      document.body.innerHTML=`<main class="public-error"><h1>Agreement unavailable</h1><p>${esc(payload.error||'This agreement link is invalid or has expired.')}</p></main>`;
      return;
    }
    state=clone(payload.agreement.studioState||defaultState());
    state.status=payload.agreement.status||state.status;
    publicSignatory=payload.signatory||null;
    renderAll();
    setPublicPresentation();
    const actions=document.querySelector('.actions');
    if(actions){
      actions.innerHTML='';
      const status=document.createElement('span'); status.className='statusline'; status.textContent=publicSignatory?.status==='Accepted'?'Accepted agreement':'Secure agreement review'; actions.appendChild(status);
      if(publicSignatory?.status!=='Accepted'){
        const button=document.createElement('button'); button.className='btn primary'; button.id='publicAcceptBtn'; button.textContent='Accept agreement'; button.onclick=()=>openSigning(); actions.appendChild(button);
      }else{
        const print=document.createElement('button'); print.className='btn secondary'; print.textContent='Print / save PDF'; print.onclick=()=>window.print(); actions.appendChild(print);
      }
    }
    document.querySelector('#templateBtn')?.remove();
    document.querySelector('#saveBtn')?.remove();
    document.querySelector('#exportBtn')?.remove();
    document.querySelector('#issueBtn')?.remove();
    document.querySelector('#editTextBtn')?.remove();
    const acceptButton=document.querySelector('#acceptAgreement'); if(acceptButton) acceptButton.onclick=acceptPublicAgreement;
  }
  async function acceptPublicAgreement(){
    if(!document.querySelector('#checkRead')?.checked||!document.querySelector('#checkFees')?.checked||!document.querySelector('#checkDocs')?.checked||!document.querySelector('#typedName')?.value.trim()||!sigDrawn){ toast('Complete all acceptance confirmations and the signature'); return; }
    const signatureData=document.querySelector('#sigCanvas').toDataURL('image/png');
    const response=await fetch(`/api/agreement?token=${encodeURIComponent(publicToken)}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'accept',typedName:document.querySelector('#typedName').value.trim(),signatureData,declarations:{read:true,fees:true,codeOfConduct:true}})});
    const payload=await response.json().catch(()=>({}));
    if(!response.ok){ toast(payload.error||'Agreement acceptance failed'); return; }
    state.status=payload.agreementStatus||'Accepted';
    document.querySelector('#signModal')?.classList.add('hidden');
    toast('Agreement accepted');
    setTimeout(()=>location.reload(),900);
  }
  window.__THIS_AGREEMENT_INIT__=initFromCrm;
  window.addEventListener('message',event=>{
    if(event.origin!==CRM_ORIGIN||event.source!==window.parent) return;
    const message=event.data||{};
    if(message.type==='THIS_AGREEMENT_INIT') initFromCrm(message.payload||{});
    if(message.type==='THIS_AGREEMENT_REQUEST_SNAPSHOT') emitSnapshot(message.reason||'request');
    if(message.type==='THIS_AGREEMENT_ISSUED'){
      if(message.agreementSet){ state.status=message.agreementSet.status||'Sent'; state.sentAt=message.agreementSet.issuedAt||new Date().toISOString(); }
      document.querySelector('#issueModal')?.classList.add('hidden');
      renderAll();
      toast(message.message||'Agreement issued');
    }
  });
  window.addEventListener('load',()=>{
    const token=new URLSearchParams(location.search).get('token');
    if(token){ loadPublicReview(token).catch(error=>{document.body.innerHTML=`<main class="public-error"><h1>Agreement unavailable</h1><p>${esc(error.message||String(error))}</p></main>`}); return; }
    setCrmPresentation();
    if(window.parent!==window){
      const saveButton=document.querySelector('#saveBtn'); if(saveButton) saveButton.onclick=()=>{ save(); setTimeout(()=>emitSnapshot('save'),20); };
      const simulate=document.querySelector('#simulateSend'); if(simulate) simulate.onclick=()=>{ post('THIS_AGREEMENT_ISSUE_REQUEST',{snapshot:currentSnapshot(),emailSubject:state.emailSubject,emailBody:state.emailBody}); };
      const saveTemplate=document.querySelector('#saveTemplate'); if(saveTemplate) saveTemplate.onclick=()=>{save();emitTemplate('save');toast('Template draft sent to CRM')};
      const publishTemplateButton=document.querySelector('#publishTemplate'); if(publishTemplateButton) publishTemplateButton.onclick=()=>{publishTemplate();setTimeout(()=>emitTemplate('publish'),30)};
      const announceReady=()=>{ if(!crmInitialised) post('THIS_AGREEMENT_READY'); };
      announceReady();
      readyHandshakeTimer=window.setInterval(announceReady,750);
      window.setTimeout(()=>{ if(readyHandshakeTimer) window.clearInterval(readyHandshakeTimer); },15000);
    }
    const acceptButton=document.querySelector('#acceptAgreement'); if(acceptButton&&publicToken) acceptButton.onclick=acceptPublicAgreement;
  });
})();
